  "legal_privacy_body": "ଆପଣଙ୍କ CCTV କୋଟେସନ୍ ପ୍ରସ୍ତୁତ କରିବାକୁ, ଇନଷ୍ଟଲେସନ୍ ବୁକ୍ କରିବାକୁ ଏବଂ 18% GST ୱାରେଣ୍ଟି ବିଲ୍ ଦେବାକୁ ହିଁ ଆମେ ଆପଣଙ୍କ ନାମ, ମୋବାଇଲ୍ ନମ୍ବର, ପିନକୋଡ୍ ଓ ସ୍ଥାନ ତଥ୍ୟ ନେଉଛୁ। ଆମେ ଆପଣଙ୍କ ତଥ୍ୟ କେବେ ବିକୁନାହୁଁ। ଅପଡେଟ୍ କିମ୍ବା ଡିଲିଟ୍ ପାଇଁ hello@cctvquotation.com ରେ ଇମେଲ୍ କରନ୍ତୁ।",
  "legal_privacy_title": "ଗୋପନୀୟତା ନୀତି — ମୁଖ୍ୟ ବିନ୍ଦୁ",
  "legal_terms_body": "କୋଟେସନରେ 18% GST, ଅସଲି ସିଲ୍‌ଡ୍ ହାର୍ଡୱେର ଏବଂ ଷ୍ଟାଣ୍ଡାର୍ଡ କେବୁଲ୍ (15ମି/କ୍ୟାମେରା) ଅନ୍ତର୍ଭୁକ୍ତ। ପେମେଣ୍ଟ ପର୍ଯ୍ୟାୟ: ₹500 ବୁକିଂ ଟୋକନ୍, ସାମଗ୍ରୀ ଡେଲିଭରିରେ 90% ଏବଂ ମୋବାଇଲ୍ ଲାଇଭ୍ ଟେଷ୍ଟିଂ ପରେ 10%। ବ୍ରାଣ୍ଡ ୱାରେଣ୍ଟି ସହ 1 ବର୍ଷର ସର୍ଭିସ୍ ସପୋର୍ଟ ମିଳେ।",
