  "faq_1_q": "କୋଟେସନ୍ ଦାମ୍‌ରେ GST ଅନ୍ତର୍ଭୁକ୍ତ ଅଛି କି?",
  "faq_1_a": "ହଁ, ନିଶ୍ଚିତ। CCTVQuotation ର ପ୍ରତିଟି କୋଟେସନ୍‌ରେ 18% GST ଆଗରୁ ସାମିଲ ଅଛି — କୌଣସି ଲୁଚା ଖର୍ଚ୍ଚ ନାହିଁ। ଏଥିରେ କ୍ୟାମେରା, DVR/NVR, କେବଲ୍ ଏବଂ ସମ୍ପୂର୍ଣ୍ଣ ଫିଟିଂ ଅନ୍ତର୍ଭୁକ୍ତ।",
