  "faq_3_q": "4-କ୍ୟାମେରା CCTV ସେଟଅପ୍‌ର ଖର୍ଚ୍ଚ କେତେ ପଡ଼େ?",
  "faq_3_a": "ସମ୍ପୂର୍ଣ୍ଣ 4-କ୍ୟାମେରା ସେଟଅପ୍ ବ୍ରାଣ୍ଡ୍ ଏବଂ ଫିଚର୍ ଅନୁସାରେ ପ୍ରାୟ ₹14,200 ରୁ ₹18,000 ରୁ ଆରମ୍ଭ ହୁଏ। ସମସ୍ତ ଦାମ୍‌ରେ 18% GST, କେବଲ୍ ଏବଂ ଫିଟିଂ ସାମିଲ ଅଛି।",
